const getIconForFilePath = (filePath: string) => {
	const moduleType = getModuleTypeFromFilePath({
		filePath
	})
	switch (moduleType) {
		case ModuleType.PAGE:
		case ModuleType.COMPONENT:
		case ModuleType.AUTH_PAGE_SIGN_IN:
		case ModuleType.AUTH_PAGE_LOGOUT:
		case ModuleType.AUTH_PAGE_SIGN_UP:
		case ModuleType.DESIGN_SYSTEM_COMPONENT:
		case ModuleType.DESIGN_SYSTEM_PAGE:
		case ModuleType.EXPO_PAGE:
			return svgReact()
		case ModuleType.FUNCTION: {
			return svgJavascript()
		}
		case ModuleType.FILE: {
			if (filePath.endsWith('.jsx')) {
				return svgReact()
			}
			if (filePath.endsWith('.js')) {
				return svgJavascript()
			}
			return svgPage()
		}
		default: {
			const exhaustiveCheck: never = moduleType
			return exhaustiveCheck
		}
	}
}

export interface FileTreeRef {
	scrollToFile: (filePath: string) => void
}

export interface FileTreeProps {
	fs: Record<string, string>
	filePath: string | null
	expandedItems?: string[]
	onExpandedItemsChange?: (items: string[]) => void
	onSelect?: (filePath: string) => void
	style?: any
}

type FileTreeNode = TreeNode<string> & {
	isFolder?: boolean
	fullPath?: string
}

function buildTreeDataFromPaths(paths: string[]): FileTreeNode[] {
	type Mutable = {
		id: string
		name: string
		isFolder: boolean
		childrenMap: Map<string, Mutable>
	}

	const root: Mutable = {
		id: '/',
		name: '/',
		isFolder: true,
		childrenMap: new Map()
	}

	const normalize = (p: string) => {
		if (!p) return '/'
		const withSlash = p.startsWith('/') ? p : `/${p}`
		return withSlash.replace(/\/+/g, '/')
	}

	for (const rawPath of paths) {
		const path = normalize(rawPath)
		const parts = path.split('/').filter(Boolean)
		let current = root
		let currentPath = ''

		for (let i = 0; i < parts.length; i++) {
			const part = parts[i]!
			const isLast = i === parts.length - 1
			currentPath = `${currentPath}/${part}`

			let child = current.childrenMap.get(currentPath)
			if (!child) {
				child = {
					id: currentPath,
					name: part,
					isFolder: !isLast,
					childrenMap: new Map()
				}
				current.childrenMap.set(currentPath, child)
			} else {
				if (!child.isFolder && !isLast) child.isFolder = true
			}

			current = child
		}
	}

	const toTreeNodes = (node: Mutable): FileTreeNode => {
		const children = Array.from(node.childrenMap.values())
			.sort((a, b) => {
				if (a.isFolder !== b.isFolder) return a.isFolder ? -1 : 1
				return a.name.localeCompare(b.name)
			})
			.map(toTreeNodes)

		return {
			id: node.id,
			name: node.name,
			children: node.isFolder ? (children.length ? children : []) : undefined,
			isFolder: node.isFolder,
			fullPath: node.id
		}
	}

	return Array.from(root.childrenMap.values())
		.sort((a, b) => {
			if (a.isFolder !== b.isFolder) return a.isFolder ? -1 : 1
			return a.name.localeCompare(b.name)
		})
		.map(toTreeNodes)
}

function FileNodeRow({
	node,
	level,
	isExpanded,
	onExpand,
	onSelect,
	onToggleExpand
}: NodeRowProps<string> & {
	node: FileTreeNode
	onSelect?: (filePath: string) => void
	onToggleExpand?: (nodeId: string) => void
}) {
	const isFolder = !!node.isFolder
	const indent = level * 12
	const nodeId = node.id

	return (
		<View style={styles.rowOuter}>
			<Pressable
				onPress={() => {
					if (isFolder) {
						if (onToggleExpand && nodeId) {
							onToggleExpand(nodeId)
						} else if (onExpand) {
							onExpand()
						}
					} else if (node.fullPath && onSelect) {
						onSelect(node.fullPath)
					}
				}}
				onPressIn={() => {
					if (isFolder) {
						if (onToggleExpand && nodeId) {
							onToggleExpand(nodeId)
						} else if (onExpand) {
							onExpand()
						}
					} else if (node.fullPath && onSelect) {
						onSelect(node.fullPath)
					}
				}}
				hitSlop={{ left: 10, right: 10 }}
				style={({ pressed }) => [
					styles.row,
					{ paddingLeft: indent + 10 },
					pressed && styles.rowPressed
				]}
			>
				{isFolder ? (
					isExpanded ? (
						<View style={styles.icon}>
							<ChevronDownIcon />
							<FolderOpenIcon />
						</View>
					) : (
						<View style={styles.icon}>
							<ChevronRightIcon />
							<FolderClosedIcon />
						</View>
					)
				) : node.fullPath ? (
					<View style={styles.icon}>{getIconForFilePath(node.fullPath)}</View>
				) : null}

				<Text style={styles.label} numberOfLines={1}>
					{node.name}
				</Text>
			</Pressable>
		</View>
	)
}

const FileTreeComponent = forwardRef<FileTreeRef, FileTreeProps>(
	(
		{
			fs,
			filePath,
			expandedItems: externalExpanded,
			onExpandedItemsChange,
			onSelect,
			style
		},
		ref
	) => {
		const treeRef = useRef<TreeViewRef<string> | null>(null)

		const data = useMemo(() => {
			const paths = Object.keys(fs)
			return buildTreeDataFromPaths(paths)
		}, [fs])

		const [internalExpanded, setInternalExpanded] = useState<string[]>([])
		const expandedItems = externalExpanded ?? internalExpanded
		const setExpandedItems = onExpandedItemsChange ?? setInternalExpanded
		const isManualToggleRef = useRef(false)

		useImperativeHandle(ref, () => ({
			scrollToFile: (targetFilePath: string) => {
				treeRef.current?.scrollToNodeID?.({
					nodeId: targetFilePath,
					expandScrolledNode: true,
					animated: true,
					viewPosition: 0.3
				})
			}
		}))

		const handleToggleExpand = (nodeId: string) => {
			const findNode = (
				nodes: FileTreeNode[],
				id: string
			): FileTreeNode | null => {
				for (const node of nodes) {
					if (node.id === id) {
						return node
					}
					if (node.children) {
						const found = findNode(node.children, id)
						if (found) return found
					}
				}
				return null
			}

			const getAllDescendantIds = (node: FileTreeNode): string[] => {
				const ids: string[] = []
				if (node.children) {
					for (const child of node.children) {
						ids.push(child.id)
						if (child.children) {
							ids.push(...getAllDescendantIds(child))
						}
					}
				}
				return ids
			}

			const node = findNode(data, nodeId)

			if (!node) {
				return
			}

			isManualToggleRef.current = true
			const currentExpanded = expandedItems
			const wasExpanded = currentExpanded.includes(nodeId)

			let newExpanded: string[]
			if (wasExpanded) {
				const descendantIds = getAllDescendantIds(node)
				const idsToRemove = new Set([nodeId, ...descendantIds])
				newExpanded = currentExpanded.filter(
					(id: string) => !idsToRemove.has(id)
				)
			} else {
				newExpanded = [...currentExpanded, nodeId]
			}

			setExpandedItems(newExpanded)

			setTimeout(() => {
				isManualToggleRef.current = false
			}, 100)
		}

		const FileNodeRowWithSelect = (
			props: NodeRowProps<string> & { node: FileTreeNode }
		) => {
			return (
				<FileNodeRow
					{...props}
					onSelect={onSelect}
					onToggleExpand={handleToggleExpand}
				/>
			)
		}

		return (
			<View style={[styles.container, style]}>
				<TreeView
					ref={treeRef}
					data={data}
					preExpandedIds={expandedItems}
					key={expandedItems.join(',') || 'none'}
					onExpand={(nextExpandedIds) => {
						if (isManualToggleRef.current) {
							return
						}

						if (nextExpandedIds.length === 0 && expandedItems.length > 0) {
							return
						}

						const currentSorted = [...expandedItems].sort()
						const nextSorted = [...nextExpandedIds].sort()
						if (JSON.stringify(currentSorted) !== JSON.stringify(nextSorted)) {
							setExpandedItems(nextExpandedIds)
						}
					}}
					initialScrollNodeID={filePath ?? undefined}
					CustomNodeRowComponent={FileNodeRowWithSelect as any}
				/>
			</View>
		)
	}
)

